// Regenerates theme/style.generated.ts from theme/style.css.
//
// style.css is the only stylesheet that is maintained by hand. The generated file embeds it as a
// JavaScript string so the library keeps shipping as a single JS file (no CSS import or extra request),
// and it is committed so Hugo can build the site without running this script.
//
// Usage, from pandaqi-studio:
//   bun themes/pandaqi/assets/lib/pq-rulebook/generate-style.mjs
//   bun themes/pandaqi/assets/lib/pq-rulebook/generate-style.mjs --check
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const cssPath = join(here, "theme", "style.css");
const outputPath = join(here, "theme", "style.generated.ts");

const css = readFileSync(cssPath, "utf8");
const banner = [
    "// AUTO-GENERATED from theme/style.css. Do not edit this file directly.",
    "// Regenerate from pandaqi-studio with:",
    "//   bun themes/pandaqi/assets/lib/pq-rulebook/generate-style.mjs",
    "// The CSS is embedded so the library remains a single JavaScript file; it is committed so Hugo",
    "// can build without running a separate step.",
].join("\n");

const output = `${banner}\nexport const INLINE_STYLES = ${JSON.stringify(css)};\n`;
const check = process.argv.includes("--check");

if(check)
{
    let current = "";
    try { current = readFileSync(outputPath, "utf8"); } catch(error) { /* missing counts as stale */ }
    if(current !== output)
    {
        console.error("theme/style.generated.ts is out of date. Run generate-style.mjs.");
        process.exit(1);
    }
    console.log("theme/style.generated.ts is up to date.");
    process.exit(0);
}

writeFileSync(outputPath, output, "utf8");
console.log(`Wrote ${outputPath}`);
